for(let y=140;y<360;y+=6){
  const x=400+Math.sin(y*0.06)*-14;
  ctx.lineTo(x,y);
}
ctx.stroke();
for(let i=0;i<40;i++){
  const y=145+i*5.5;
  const x=400+Math.sin(y*0.06)*-14 + (i%2===0?-12:12);
  leaf(x,y,7+(i%3)*2,5+(i%2)*2, (i%2===0?-0.6:0.6)+(i*0.1));
}
// small flowers
ctx.fillStyle='#D97745';
for(let i=0;i<12;i++){
  const y=160+i*16;
  const x = (i%2===0)?(-4+Math.sin(y*0.05)*14) : (394+Math.sin(y*0.06)*-14);
  ctx.beginPath(); ctx.arc(x,y,2.5,0,Math.PI*2); ctx.fill();
}
